CREATE TABLE public.community_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, author_name text NOT NULL, category text NOT NULL CHECK (category IN ('Soru-Cevap','Kod İnceleme','Takım Bul','Etkinlikler','Duyuru')), title text NOT NULL CHECK (length(title) BETWEEN 5 AND 180), body text NOT NULL CHECK (length(body) BETWEEN 10 AND 10000), tags text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_posts TO authenticated; GRANT ALL ON public.community_posts TO service_role;
ALTER TABLE public.community_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY community_read ON public.community_posts FOR SELECT TO authenticated USING (true);
CREATE INDEX community_posts_created ON public.community_posts(created_at DESC);
CREATE TABLE public.community_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.community_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL, author_name text NOT NULL, body text NOT NULL CHECK (length(body) BETWEEN 1 AND 3000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_comments TO authenticated; GRANT ALL ON public.community_comments TO service_role;
ALTER TABLE public.community_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.community_comments FOR SELECT TO authenticated USING (true);
CREATE INDEX community_comments_post ON public.community_comments(post_id, created_at);
CREATE TABLE public.community_reactions (post_id uuid NOT NULL REFERENCES public.community_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL, kind text NOT NULL CHECK (kind IN ('like','save')), PRIMARY KEY(post_id,user_id,kind));
GRANT SELECT ON public.community_reactions TO authenticated; GRANT ALL ON public.community_reactions TO service_role;
ALTER TABLE public.community_reactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY reactions_read ON public.community_reactions FOR SELECT TO authenticated USING (kind = 'like' OR user_id = auth.uid());
CREATE TABLE public.community_event_registrations (event_id text NOT NULL, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id,user_id));
GRANT SELECT ON public.community_event_registrations TO authenticated; GRANT ALL ON public.community_event_registrations TO service_role;
ALTER TABLE public.community_event_registrations ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_owner_read ON public.community_event_registrations FOR SELECT TO authenticated USING (user_id = auth.uid());
COMMENT ON TABLE public.community_posts IS 'Writes restricted to authenticated server actions with fresh human verification; no direct client writes.';
COMMENT ON TABLE public.community_reactions IS 'Likes public to members; bookmarks private to owner. Writes restricted to verified server actions.';